INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21FBGMG', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the $x$-intercept of the line $4x - 7y = 28$?', NULL, $lyceon_json$[{"key":"A","text":"$(4, 0)$"},{"key":"B","text":"$(7, 0)$"},{"key":"C","text":"$(0, -4)$"},{"key":"D","text":"$(-7, 0)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting $y = 0$ in $4x - 7(0) = 28$ gives $4x = 28$, so $x = 7$. The $x$-intercept is $(7, 0)$. The point $(4, 0)$ confuses the coefficient of $x$ with the intercept value. The point $(0, -4)$ is the $y$-intercept (found by setting $x = 0$), not the $x$-intercept. The point $(-7, 0)$ introduces a sign error when dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21PTT4K', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = -2(x - 4)^2 + 11$. What is the maximum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-21$"},{"key":"B","text":"$4$"},{"key":"C","text":"$11$"},{"key":"D","text":"$-11$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $f(x) = a(x - h)^2 + k$ with $a = -2$, $h = 4$, and $k = 11$. Since $a < 0$, the parabola opens downward and the vertex $(4, 11)$ is the maximum point. The maximum value of $f(x)$ is $11$. The distractor $-21$ comes from evaluating $f(0) = -2(0 - 4)^2 + 11 = -2(16) + 11 = -32 + 11 = -21$, incorrectly checking $x = 0$ instead of the vertex. The distractor $4$ is the $x$-coordinate of the vertex, not the maximum value — the question asks for the maximum output, not the input at which it occurs. The distractor $-11$ results from a sign error, negating the $k$-value from the vertex form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22VR01U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set has $9$ values with a median of $41$. If two additional values, $17$ and $53$, are added to the data set, which of the following must be true about the new median?', NULL, $lyceon_json$[{"key":"A","text":"The new median is less than $41$."},{"key":"B","text":"The new median is equal to $41$."},{"key":"C","text":"The new median is greater than $41$."},{"key":"D","text":"The new median could be less than, equal to, or greater than $41$."}]$lyceon_json$::jsonb, 'B', NULL, E'In the original sorted data set of $9$ values, the median is the $5$th value, which is $41$. Adding $17$ (below the median) and $53$ (above the median) gives $11$ values. The new median is the $6$th value. Adding one value below and one above the original median shifts the position by one in both directions: the value that was $5$th remains in the $6$th position, so the new median is still $41$. The distractor stating the median is less than $41$ incorrectly assumes the smaller added value pulls the median down. The distractor stating greater than $41$ incorrectly assumes the larger added value pulls it up. The distractor suggesting any outcome is possible fails to recognize the symmetric effect of adding one value on each side of the median.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22Y0BSE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has the equation $(x - 5)^2 + (y + 7)^2 = 169$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$. Comparing with the given equation, $r^2 = 169$, so $r = \\sqrt{169} = 13$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23P7SBR', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A small business produces two products, X and Y. Each unit of X requires 5 hours of labor and each unit of Y requires 3 hours. The business has at most 67 hours of labor available per week. Additionally, the business must produce at least 4 units of Y per week to meet a contract obligation. If the business wants to maximize the number of units of X produced per week, what is the maximum number of units of X it can produce?', NULL, $lyceon_json$[{"key":"A","text":"10"},{"key":"B","text":"11"},{"key":"C","text":"13"},{"key":"D","text":"9"}]$lyceon_json$::jsonb, 'B', NULL, E'The constraints are \\(5x + 3y \\leq 67\\) and \\(y \\geq 4\\). To maximize \\(x\\), set \\(y\\) to its minimum value of 4. Then \\(5x + 3(4) \\leq 67\\), so \\(5x + 12 \\leq 67\\), giving \\(5x \\leq 55\\) and \\(x \\leq 11\\). The maximum is 11 units. The value 10 comes from a subtraction error such as computing \\(67 - 12\\) as 50 instead of 55. The value 13 ignores the minimum Y constraint entirely and computes \\(\\lfloor 67/5 \\rfloor = 13\\). The value 9 results from using \\(y = 5\\) instead of the minimum of 4, obtaining \\(\\lfloor 52/5 \\rfloor = 10\\), then subtracting one extra unit.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24GOWWY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'A right triangle has legs of length $7$ and $24$. What is the length of the hypotenuse?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'By the Pythagorean theorem, the hypotenuse $c$ satisfies $c^2 = 7^2 + 24^2 = 49 + 576 = 625$. Taking the square root, $c = \\sqrt{625} = 25$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25QHUCJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a class of 31 students, 18 play soccer, 13 play basketball, and 5 play both soccer and basketball. If a student is chosen at random from those who play soccer, what is the probability that the student also plays basketball?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{5}{31}\\)"},{"key":"B","text":"\\(\\dfrac{5}{18}\\)"},{"key":"C","text":"\\(\\dfrac{13}{31}\\)"},{"key":"D","text":"\\(\\dfrac{5}{13}\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the student plays soccer, the sample space is the 18 soccer players. Of those, 5 also play basketball, so the conditional probability is 5/18. The distractor 5/31 divides by the total class size instead of the number of soccer players, ignoring the given condition. The distractor 13/31 gives the unconditional probability of playing basketball. The distractor 5/13 divides by the number of basketball players rather than soccer players, reversing the condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2824L0X', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A function $f$ is defined by $f(x) = -4x + 19$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-31$"},{"key":"B","text":"$-12$"},{"key":"C","text":"$7$"},{"key":"D","text":"$31$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 3$: $f(3) = -4(3) + 19 = -12 + 19 = 7$. The value $-31$ comes from computing $-4(3) - 19 = -31$, incorrectly subtracting $19$ instead of adding. The value $-12$ stops at $-4(3) = -12$ without adding $19$. The value $31$ drops the negative sign, computing $4(3) + 19 = 31$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28FACEG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What is the value of $x$ that satisfies the equation $$\\frac{3(4x - 1)}{5} - 2 = \\frac{2(3x + 7)}{5}\\;?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9/2', ARRAY['9/2', '4.5'], E'Multiplying both sides by $5$ gives $3(4x - 1) - 10 = 2(3x + 7)$. Expanding: $12x - 3 - 10 = 6x + 14$, which simplifies to $12x - 13 = 6x + 14$. Subtracting $6x$ from both sides: $6x - 13 = 14$. Adding $13$: $6x = 27$. Dividing by $6$: $x = \\frac{27}{6} = \\frac{9}{2}$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM299V2M7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $h$ is defined by $h(x) = ax + b$, where $a$ and $b$ are constants. If $h(2) = 13$ and $h(-3) = -17$, what is the value of $h(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$-17$"},{"key":"B","text":"$7$"},{"key":"C","text":"$41$"},{"key":"D","text":"$43$"}]$lyceon_json$::jsonb, 'D', NULL, E'From $h(2) = 2a + b = 13$ and $h(-3) = -3a + b = -17$, subtracting the second equation from the first gives $5a = 30$, so $a = 6$. Substituting back: $2(6) + b = 13$, so $b = 1$. Therefore $h(7) = 6(7) + 1 = 43$. The value $-17$ results from a sign error that yields $a = -6$ and $b = 25$, giving $h(7) = -42 + 25 = -17$. The value $7$ comes from computing $a + b = 7$ and confusing that sum with $h(7)$. The value $41$ arises from an arithmetic slip that produces $b = -1$ instead of $b = 1$, giving $42 - 1 = 41$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ADZSJ8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone and a hemisphere share the same circular base with radius $6$ cm. The cone has a height of $11$ cm. What is the total volume of the combined solid, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$276\\pi$"},{"key":"B","text":"$132\\pi$"},{"key":"C","text":"$144\\pi$"},{"key":"D","text":"$396\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of the cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(36)(11) = 132\\pi$ cm$^3$. The volume of the hemisphere is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(216) = 144\\pi$ cm$^3$. The total volume is $132\\pi + 144\\pi = 276\\pi$ cm$^3$. The value $132\\pi$ gives only the cone volume, omitting the hemisphere. The value $144\\pi$ gives only the hemisphere volume, omitting the cone. The value $396\\pi$ comes from using $\\pi r^2 h = 396\\pi$ for the cone (forgetting the $\\frac{1}{3}$ factor) and then not adding the hemisphere at all.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ATJQE0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $13$ feet and a width of $6$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '78', ARRAY['78'], E'The area of a rectangle is length times width: $A = 13 \\times 6 = 78$ square feet.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AVWB0D', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $g$ is defined by $g(x) = \\frac{7x - 11}{3}$. For what value of $x$ does $g(x) = 15$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Setting $\\frac{7x - 11}{3} = 15$ and multiplying both sides by $3$ gives $7x - 11 = 45$. Adding $11$ to both sides: $7x = 56$. Dividing by $7$: $x = 8$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BO9EF9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher collected data from 1,200 adults and found that those who reported eating breakfast daily had lower average cholesterol levels than those who reported skipping breakfast. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast daily causes lower cholesterol levels."},{"key":"B","text":"There is an association between eating breakfast daily and lower cholesterol levels."},{"key":"C","text":"Skipping breakfast causes higher cholesterol levels."},{"key":"D","text":"Adults who eat breakfast daily are healthier in every measurable way than those who skip breakfast."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study (the researcher collected data on existing behaviors rather than randomly assigning participants to eat or skip breakfast), the most appropriate conclusion is that there is an association between eating breakfast daily and lower cholesterol. The claim that eating breakfast causes lower cholesterol asserts causation, which cannot be established from an observational study due to potential confounding variables. The claim that skipping breakfast causes higher cholesterol similarly asserts causation in the reverse direction. The claim that breakfast eaters are healthier in every measurable way overgeneralizes far beyond the data, which only measured cholesterol levels.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CD6Z5X', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of the equation $x^2 + 3x - 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Factor the quadratic: $x^2 + 3x - 28 = (x + 7)(x - 4) = 0$. Setting each factor to zero gives $x = -7$ or $x = 4$. Since $-7$ is negative, the only positive solution is $4$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CSZXVX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 3 \\cdot 2^x - 5$. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$1$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $y$-intercept occurs when $x = 0$. Evaluating: $f(0) = 3 \\cdot 2^0 - 5 = 3(1) - 5 = 3 - 5 = -2$. The distractor $-5$ comes from reading only the constant term without evaluating $3 \\cdot 2^0$. The distractor $1$ results from computing $3 \\cdot 2^1 - 5 = 6 - 5 = 1$, using $2^1$ instead of $2^0$. The distractor $3$ comes from evaluating $3 \\cdot 2^0 = 3$ but forgetting to subtract $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D2UJ0D', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A chemist has two acid solutions. Solution P is 23% acid and Solution Q is 61% acid. The chemist needs to mix the two solutions to produce exactly 19 liters of a 37% acid solution. How many liters of Solution Q are needed?', NULL, $lyceon_json$[{"key":"A","text":"7"},{"key":"B","text":"12"},{"key":"C","text":"9"},{"key":"D","text":"5"}]$lyceon_json$::jsonb, 'A', NULL, E'Let \\(p\\) be the liters of Solution P and \\(q\\) be the liters of Solution Q. The system is \\(p + q = 19\\) and \\(0.23p + 0.61q = 0.37(19) = 7.03\\). Substituting \\(p = 19 - q\\): \\(0.23(19 - q) + 0.61q = 7.03\\), giving \\(4.37 - 0.23q + 0.61q = 7.03\\), so \\(0.38q = 2.66\\) and \\(q = 7\\). The value 12 is the number of liters of Solution P, not Solution Q, resulting from misreading which quantity the question asks for. The value 9 arises from incorrectly setting up the acid concentration equation, such as using 37 instead of 0.37. The value 5 results from an arithmetic error when dividing 2.66 by 0.38.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D6PU2H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A survey of 200 employees recorded whether they commute by train or by car and whether they arrive on time or late. Of the 200 employees, 87 commute by train and 113 commute by car. Among train commuters, 69 arrive on time. Among car commuters, 79 arrive on time. If an employee who arrived late is selected at random, what is the probability that this employee commutes by car?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{34}{52}\\)"},{"key":"B","text":"\\(\\dfrac{18}{52}\\)"},{"key":"C","text":"\\(\\dfrac{34}{113}\\)"},{"key":"D","text":"\\(\\dfrac{34}{200}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Late train commuters: 87 − 69 = 18. Late car commuters: 113 − 79 = 34. Total late employees: 18 + 34 = 52. The probability that a randomly selected late employee commutes by car is 34/52 (equivalently 17/26). The distractor 18/52 gives the probability that a late employee commutes by train, confusing train for car. The distractor 34/113 divides late car commuters by all car commuters, which answers a different conditional question. The distractor 34/200 divides late car commuters by the total number of employees, ignoring the condition of being late.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DKTVQ5', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of \\$11 plus \\$4 per mile. A customer has at most \\$47 to spend on delivery. Which inequality represents the number of miles \\(m\\) the customer can afford, and what is the maximum whole number of miles?', NULL, $lyceon_json$[{"key":"A","text":"\\(4m + 11 \\leq 47\\); 9 miles"},{"key":"B","text":"\\(4m + 11 \\leq 47\\); 10 miles"},{"key":"C","text":"\\(4m - 11 \\leq 47\\); 14 miles"},{"key":"D","text":"\\(11m + 4 \\leq 47\\); 3 miles"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is \\(4m + 11\\), which must be at most 47, giving \\(4m + 11 \\leq 47\\). Solving: \\(4m \\leq 36\\), so \\(m \\leq 9\\). The maximum whole number of miles is 9. The distractor stating 10 miles uses the correct inequality but incorrectly rounds up from the exact answer of 9. The distractor with \\(4m - 11\\) subtracts the flat fee instead of adding it, inflating the result to 14. The distractor with \\(11m + 4\\) reverses the per-mile rate and flat fee, yielding only 3 miles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E190R5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the equation $3x^2 - 14x + k = 0$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{49}{3}$"},{"key":"B","text":"$49$"},{"key":"C","text":"$\\frac{14}{3}$"},{"key":"D","text":"$\\frac{7}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'A quadratic $ax^2 + bx + c = 0$ has exactly one real solution when the discriminant equals zero: $b^2 - 4ac = 0$. Here $a = 3$, $b = -14$, and $c = k$, so $(-14)^2 - 4(3)(k) = 0$, giving $196 - 12k = 0$, and therefore $k = \\frac{196}{12} = \\frac{49}{3}$. The distractor $49$ results from computing $b^2 / 4 = 196/4 = 49$, omitting the factor of $a = 3$ in the denominator. The distractor $\\frac{14}{3}$ comes from computing $|b|/a = 14/3$, confusing the discriminant condition with a ratio of coefficients. The distractor $\\frac{7}{3}$ arises from an arithmetic error such as computing $\\frac{14}{6}$ instead of $\\frac{196}{12}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E4WYCG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $41°$ and the exterior angle at vertex $R$ is $109°$. What is the measure of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$68°$"},{"key":"B","text":"$71°$"},{"key":"C","text":"$30°$"},{"key":"D","text":"$39°$"}]$lyceon_json$::jsonb, 'A', NULL, E'The exterior angle at vertex $R$ equals the sum of the two non-adjacent interior angles: angle $P$ + angle $Q$ = $109°$. Therefore angle $Q$ = $109° - 41° = 68°$. The value $71°$ comes from computing the interior angle at $R$ as $180° - 109° = 71°$ and incorrectly reporting that as angle $Q$. The value $30°$ comes from subtracting both $109°$ and $41°$ from $180°$, treating the exterior angle as an interior angle. The value $39°$ results from a digit-transposition error when computing $109° - 41°$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EDNHZW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the average daily temperature (in $°F$) and the number of ice cream cones sold at a stand. The line of best fit is $y = 3.7x - 118$, where $x$ is the temperature and $y$ is the number of cones sold. What is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each $1°F$ increase in temperature, the predicted number of cones sold increases by $3.7$."},{"key":"B","text":"For each additional cone sold, the temperature is predicted to increase by $3.7°F$."},{"key":"C","text":"When the temperature is $0°F$, the predicted number of cones sold is $3.7$."},{"key":"D","text":"For each $3.7°F$ increase in temperature, the predicted number of cones sold increases by $1$."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $3.7$ means that for each $1°F$ increase in average daily temperature, the model predicts an increase of $3.7$ ice cream cones sold. The distractor stating temperature increases by $3.7°F$ per cone reverses the dependent and independent variables. The distractor describing $3.7$ as the predicted sales at $0°F$ confuses the slope with the $y$-intercept. The distractor stating a $3.7°F$ increase yields $1$ additional cone inverts the slope relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ERPBWH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveyed a random sample of 400 voters and found that 47% plan to vote for Candidate X, with a margin of error of 3.1 percentage points at a 95% confidence level. A second researcher surveyed a random sample of 1,600 voters from the same population and found that 49% plan to vote for Candidate X. Which of the following statements is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The second survey's margin of error is likely larger than 3.1 percentage points because the proportion changed."},{"key":"B","text":"The second survey's margin of error is likely about half of 3.1 percentage points because quadrupling the sample size halves the margin of error."},{"key":"C","text":"The second survey's margin of error is likely about 1.55 percentage points because the margin of error is inversely proportional to the sample size."},{"key":"D","text":"The second survey is unreliable because its result differs from the first survey's result."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely proportional to the square root of the sample size. Quadrupling the sample size from 400 to 1,600 means dividing the margin of error by √4 = 2, giving approximately 3.1/2 ≈ 1.55 percentage points. The claim that the margin of error is larger because the proportion changed confuses the effect of sample size with the effect of proportion changes, which have a much smaller impact. The statement that the margin of error is inversely proportional to the sample size (not its square root) would yield about 3.1/4 ≈ 0.78, which is incorrect. The claim that the second survey is unreliable because results differ misunderstands that different random samples can produce different estimates within the expected range of sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FHEULB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A car travels $203$ miles using $7$ gallons of gasoline. A truck travels the same route but uses gasoline at a rate that is $\\frac{3}{2}$ times the car''s rate. How many gallons of gasoline does the truck use for the same $203$-mile trip? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21/2', ARRAY['21/2', '10.5'], E'The car''s fuel consumption rate is $\\frac{7}{203}$ gallons per mile. The truck uses gasoline at $\\frac{3}{2}$ times this rate, so the truck''s rate is $\\frac{3}{2} \\times \\frac{7}{203} = \\frac{21}{406} = \\frac{3}{58}$ gallons per mile. For $203$ miles, the truck uses $\\frac{3}{58} \\times 203 = \\frac{609}{58} = \\frac{21}{2} = 10.5$ gallons.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GW3WMN', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of \\(x\\) satisfies the inequality \\(3x - 7 > 14\\)?', NULL, $lyceon_json$[{"key":"A","text":"5"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"3"}]$lyceon_json$::jsonb, 'C', NULL, E'Solving \\(3x - 7 > 14\\) gives \\(3x > 21\\), so \\(x > 7\\). Among the choices, only 8 is greater than 7. The value 7 fails because the inequality is strict (not \\(\\geq\\)). The value 5 results from an arithmetic slip such as dividing 14 by 3 instead of 21. The value 3 produces \\(3(3) - 7 = 2\\), which is far less than 14.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HLB6HK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the relationship between the dosage $d$ (in milligrams) of a nutrient supplement and the growth $g$ (in centimeters) of a plant over $4$ weeks using the equation $g = -0.03d^2 + 1.74d + 2.1$. According to this model, at what dosage does the plant achieve maximum growth?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$29$"},{"key":"C","text":"$58$"},{"key":"D","text":"$87$"}]$lyceon_json$::jsonb, 'B', NULL, E'The growth function is a downward-opening parabola ($a = -0.03 < 0$), so the maximum occurs at the vertex. The $d$-coordinate of the vertex is $d = -\\frac{b}{2a} = -\\frac{1.74}{2(-0.03)} = -\\frac{1.74}{-0.06} = 29$. The distractor $27$ results from a rounding or arithmetic error in the division. The distractor $58$ comes from computing $\\frac{1.74}{0.03}$, omitting the factor of $2$ in the denominator. The distractor $87$ results from computing $\\frac{1.74}{0.02}$, using only $a$ instead of $2a$ and miscalculating.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HPL4CI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new type of fertilizer increases tomato yield. She randomly assigns 40 tomato plants to receive the new fertilizer and 40 tomato plants to receive no fertilizer. After 8 weeks, she compares the average yield of the two groups. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"An observational study, because the researcher observed the plants"},{"key":"B","text":"A survey, because data was collected from each plant"},{"key":"C","text":"An experiment, because treatments were randomly assigned to subjects"},{"key":"D","text":"An experiment, because the researcher measured a quantitative outcome"}]$lyceon_json$::jsonb, 'C', NULL, E'This is an experiment because the researcher randomly assigned treatments (fertilizer vs. no fertilizer) to subjects (tomato plants). The defining feature of an experiment is random assignment of treatments. Calling it an observational study because the researcher observed plants confuses observation (data collection) with an observational study design (no treatment imposed). Calling it a survey misapplies the term, which refers to collecting self-reported data from people. Identifying it as an experiment because a quantitative outcome was measured gives the right label but the wrong reason — measuring a quantitative outcome does not distinguish experiments from observational studies; random assignment of treatments does.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HZ561W', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $53°$. What is the measure of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$53°$"},{"key":"B","text":"$127°$"},{"key":"C","text":"$37°$"},{"key":"D","text":"$143°$"}]$lyceon_json$::jsonb, 'A', NULL, E'Alternate interior angles formed by a transversal cutting two parallel lines are congruent, so the other angle also measures $53°$. The value $127°$ results from computing $180° - 53°$, which gives the supplementary angle rather than the alternate interior angle. The value $37°$ results from computing $90° - 53°$, confusing the concept with complementary angles. The value $143°$ results from adding $90°$ to $53°$, which has no geometric basis in this context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IKAUVQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store increases the price of an item by $40\\%$, and then offers a $25\\%$ discount on the new price. The final price is what percent of the original price?', NULL, $lyceon_json$[{"key":"A","text":"$95\\%$"},{"key":"B","text":"$100\\%$"},{"key":"C","text":"$105\\%$"},{"key":"D","text":"$115\\%$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let the original price be $P$. After a $40\\%$ increase, the price is $1.40P$. After a $25\\%$ discount on the new price, the final price is $0.75 \\times 1.40P = 1.05P$, which is $105\\%$ of the original. The distractor $95\\%$ incorrectly computes $1.40 \\times 0.60$ instead of $1.40 \\times 0.75$, confusing the discount percentage. The distractor $100\\%$ assumes the increase and decrease cancel out, which is incorrect because the percentages are applied to different bases. The distractor $115\\%$ results from subtracting the percentages ($140\\% - 25\\% = 115\\%$) rather than multiplying the factors.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IW1SW6', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sells adult tickets for \\$13 each and student tickets for \\$7 each. For a particular show, 83 tickets were sold for a total revenue of \\$893. How many student tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"31"},{"key":"B","text":"52"},{"key":"C","text":"38"},{"key":"D","text":"45"}]$lyceon_json$::jsonb, 'A', NULL, E'Let \\(a\\) be the number of adult tickets and \\(s\\) the number of student tickets. The system is \\(a + s = 83\\) and \\(13a + 7s = 893\\). Substituting \\(a = 83 - s\\): \\(13(83 - s) + 7s = 893\\), which gives \\(1079 - 13s + 7s = 893\\), so \\(-6s = -186\\) and \\(s = 31\\). The value 52 is the number of adult tickets, not student tickets, resulting from answering the wrong quantity. The value 38 arises from setting up the revenue equation with swapped prices (using 7 for adults and 13 for students). The value 45 comes from an arithmetic error during the simplification step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JNPY1G', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 - 25}{2x + 5}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5$"},{"key":"B","text":"$2x - 5$"},{"key":"C","text":"$4x - 5$"},{"key":"D","text":"$2x - \\frac{5}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Recognize $4x^2 - 25$ as a difference of squares: $(2x)^2 - 5^2 = (2x + 5)(2x - 5)$. Dividing by $2x + 5$ cancels the common factor, leaving $2x - 5$. The distractor $2x + 5$ results from a sign error, as if the factorization were $(2x + 5)(2x + 5)$ instead of $(2x + 5)(2x - 5)$. The distractor $4x - 5$ comes from incorrectly treating the division as splitting terms: $4x^2 \\div 2x = 2x$ and $25 \\div 5 = 5$, which happens to give the right numerical answer by coincidence of this example but reflects a flawed method — however, $4x - 5$ does NOT equal $2x - 5$ for general $x$, confirming it is wrong. The distractor $2x - \\frac{5}{2}$ arises from dividing $5$ by $2$ rather than canceling the full binomial factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K00XYM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 residents of a city found that 62% support a proposed park renovation. The margin of error is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between 58% and 66% of all city residents likely support the park renovation."},{"key":"B","text":"Exactly 62% of all city residents support the park renovation."},{"key":"C","text":"Between 62% and 66% of all city residents likely support the park renovation."},{"key":"D","text":"Of the 250 residents surveyed, between 58% and 66% support the park renovation."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of 4 percentage points means the plausible range for the true population proportion is 62% ± 4%, which is 58% to 66%. The statement that exactly 62% of all residents support the renovation treats the sample statistic as the exact population parameter. The range 62% to 66% only adds the margin of error in one direction, giving an asymmetric interval. The claim that the interval applies to the 250 surveyed residents confuses the sample (which is known) with the population being estimated.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KDTN1F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'grid_in', E'A random sample of 900 adults in a city found that 306 regularly use public transit. The margin of error for this estimate at the 95% confidence level is approximately \\(\\dfrac{1}{\\sqrt{n}}\\), where \\(n\\) is the sample size. To reduce the margin of error to one-third of its current value, the researcher would need to survey a total of how many adults?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8100', ARRAY['8100'], E'The current margin of error is approximately 1/√900 = 1/30. To reduce the margin of error to one-third of its current value, the new margin of error must be 1/90. Setting 1/√n = 1/90 gives √n = 90, so n = 8,100. Equivalently, reducing the margin of error by a factor of 3 requires multiplying the sample size by 3² = 9, and 900 × 9 = 8,100. A common error is to merely triple the sample size (getting 2,700), which would only reduce the margin of error by a factor of √3. Another common error is to divide by 3 instead of multiplying (getting 300), reversing the relationship between sample size and margin of error.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KLOW9F', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $5(x - 3) = 40$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$8$"},{"key":"C","text":"$11$"},{"key":"D","text":"$-11$"}]$lyceon_json$::jsonb, 'C', NULL, E'Dividing both sides by $5$ gives $x - 3 = 8$, and adding $3$ to both sides yields $x = 11$. The value $8$ results from stopping at $x - 3 = 8$ without adding $3$. The value $5$ comes from subtracting $3$ from $8$ instead of adding. The value $-11$ incorrectly negates the correct answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KSRZFR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x - 3y = 21$. Line $q$ is perpendicular to line $p$ and passes through the point $(4, -1)$. Which of the following is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 5y = 7$"},{"key":"B","text":"$3x - 5y = 7$"},{"key":"C","text":"$5x - 3y = 7$"},{"key":"D","text":"$3x + 5y = 17$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $p$: $y = \\frac{5}{3}x - 7$, so the slope is $\\frac{5}{3}$. The perpendicular slope is $-\\frac{3}{5}$. Using point-slope form with $(4, -1)$: $y + 1 = -\\frac{3}{5}(x - 4)$, which gives $y = -\\frac{3}{5}x + \\frac{12}{5} - 1 = -\\frac{3}{5}x + \\frac{7}{5}$. Multiplying by $5$: $5y = -3x + 7$, so $3x + 5y = 7$. The equation $3x - 5y = 7$ uses an incorrect sign on $y$. The equation $5x - 3y = 7$ uses the original slope $\\frac{5}{3}$ instead of the perpendicular slope. The equation $3x + 5y = 17$ results from adding $1$ to $\\frac{12}{5}$ instead of subtracting, yielding $\\frac{17}{5}$ in place of $\\frac{7}{5}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LJJHRD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A solution is made by mixing chemical $X$ and chemical $Y$ in the ratio $5 : 13$. If a chemist has $910$ milliliters of chemical $Y$, how many milliliters of chemical $X$ are needed to make the solution?', NULL, $lyceon_json$[{"key":"A","text":"$250$"},{"key":"B","text":"$350$"},{"key":"C","text":"$455$"},{"key":"D","text":"$560$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of $X$ to $Y$ is $5 : 13$, so $\\frac{X}{Y} = \\frac{5}{13}$. With $Y = 910$, we get $X = \\frac{5}{13} \\times 910 = 350$ milliliters. The distractor $250$ comes from incorrectly using $\\frac{5}{18} \\times 910$, confusing the part-to-part ratio with part-to-whole. The distractor $455$ results from dividing $910$ by $2$, perhaps misreading the ratio as $1:2$. The distractor $560$ comes from an arithmetic error in evaluating $\\frac{5}{13} \\times 910$ as $\\frac{5 \\times 910}{8}$ by misremembering the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LK4CTZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A teacher records quiz scores for $8$ students: $61$, $67$, $71$, $74$, $78$, $83$, $89$, $93$. If the teacher removes the lowest score and the highest score from the data set, by how much does the range decrease?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'The original range is $93 - 61 = 32$. After removing the lowest score ($61$) and the highest score ($93$), the remaining data set is $67, 71, 74, 78, 83, 89$, which has a range of $89 - 67 = 22$. The decrease in range is $32 - 22 = 10$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LS8R0F', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3x^2 - 21x + 36$?', NULL, $lyceon_json$[{"key":"A","text":"$3(x - 3)(x - 4)$"},{"key":"B","text":"$3(x + 3)(x - 4)$"},{"key":"C","text":"$(x - 3)(x - 12)$"},{"key":"D","text":"$3(x - 6)(x - 2)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor out the greatest common factor of $3$ to get $3(x^2 - 7x + 12)$. The quadratic $x^2 - 7x + 12$ factors as $(x - 3)(x - 4)$ since $(-3)(-4) = 12$ and $(-3) + (-4) = -7$. The result is $3(x - 3)(x - 4)$. The distractor $3(x + 3)(x - 4)$ introduces a sign error: expanding gives $3(x^2 - x - 12) = 3x^2 - 3x - 36$, not the original expression. The distractor $(x - 3)(x - 12)$ expands to $x^2 - 15x + 36$, which omits the factor of $3$ and uses incorrect factor pairs. The distractor $3(x - 6)(x - 2)$ expands to $3(x^2 - 8x + 12) = 3x^2 - 24x + 36$, which has the wrong middle term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M1UJVU', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(2) = 54$ and $f(5) = 1458$, what is the value of $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $f(x) = a \\cdot b^x$, we have $f(2) = ab^2 = 54$ and $f(5) = ab^5 = 1458$. Dividing: $\\frac{ab^5}{ab^2} = b^3 = \\frac{1458}{54} = 27$, so $b = 3$. Substituting back: $a \\cdot 3^2 = 54$, giving $9a = 54$, so $a = 6$. Therefore $f(0) = a \\cdot b^0 = 6 \\cdot 1 = 6$. The distractor $2$ results from an arithmetic error such as computing $54 \\div 27 = 2$ instead of $54 \\div 9 = 6$. The distractor $3$ comes from finding $b = 3$ and reporting it as $f(0)$, confusing the base with the coefficient. The distractor $18$ comes from computing $54 \\div 3 = 18$, dividing by $b$ instead of $b^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MQU8OX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $18$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$18\\pi$"},{"key":"B","text":"$9\\pi$"},{"key":"C","text":"$81\\pi$"},{"key":"D","text":"$324\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The circumference of a circle is $C = \\pi d = 18\\pi$. The value $9\\pi$ results from using the radius instead of the diameter in the circumference formula, computing $\\pi \\times 9$. The value $81\\pi$ comes from using the area formula with the radius ($\\pi r^2 = \\pi \\times 81$) instead of the circumference formula. The value $324\\pi$ comes from computing $\\pi d^2$ instead of $\\pi d$, squaring the diameter.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MWVMV1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 7 red marbles, 4 blue marbles, and 3 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{4}{14}\\)"},{"key":"B","text":"\\(\\dfrac{4}{11}\\)"},{"key":"C","text":"\\(\\dfrac{3}{14}\\)"},{"key":"D","text":"\\(\\dfrac{7}{14}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is 7 + 4 + 3 = 14. The probability of selecting a blue marble is 4/14 (equivalently 2/7). The distractor 4/11 results from incorrectly computing the total as 11 by omitting the green marbles. The distractor 3/14 confuses the count of green marbles for blue. The distractor 7/14 uses the count of red marbles instead of blue.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
