INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OD610E', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line passes through the point $(2, 11)$ and has a slope of $3$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using $y = mx + b$: $11 = 3(2) + b$, so $11 = 6 + b$ and $b = 5$. The value $-5$ results from a sign error when subtracting $6$ from $11$. The value $6$ comes from computing $3 \\times 2 = 6$ and mistaking that product for the intercept. The value $17$ comes from adding $6$ to $11$ instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OH2O7H', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $a = \\frac{x^3 - 8}{x^2 + 2x + 4}$ for $x \\neq 2$, which of the following is equivalent to $a$?', NULL, $lyceon_json$[{"key":"A","text":"$x + 2$"},{"key":"B","text":"$x - 2$"},{"key":"C","text":"$x^2 - 2x + 4$"},{"key":"D","text":"$(x - 2)^2$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $x^3 - 8$ is a difference of cubes: $x^3 - 2^3 = (x - 2)(x^2 + 2x + 4)$. Dividing by the denominator $x^2 + 2x + 4$ cancels the common trinomial factor, leaving $x - 2$. The distractor $x + 2$ results from a sign error in the difference-of-cubes formula, confusing it with $x^3 + 8 = (x + 2)(x^2 - 2x + 4)$. The distractor $x^2 - 2x + 4$ confuses the companion factor from the sum-of-cubes identity with the result of the cancellation. The distractor $(x - 2)^2$ incorrectly squares the linear factor instead of recognizing it as the simplified quotient; at $x = 4$, $(4-2)^2 = 4$ but $a = (64 - 8)/(16 + 8 + 4) = 56/28 = 2$, confirming this is wrong.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PEUCZQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer can print $47$ pages in $2$ minutes. At this rate, how many pages can it print in $7$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$141$"},{"key":"B","text":"$164.5$"},{"key":"C","text":"$188$"},{"key":"D","text":"$329$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{47}{2} = 23.5$ pages per minute. In $7$ minutes the printer produces $23.5 \\times 7 = 164.5$ pages. The distractor $141$ results from incorrectly multiplying $47 \\times 3$ instead of using the unit rate. The distractor $188$ comes from multiplying $47 \\times 4$, treating $7$ minutes as $4$ intervals of $2$ minutes. The distractor $329$ results from multiplying $47 \\times 7$ directly, ignoring that the rate is per $2$ minutes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PGHLKC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'In a school, $64\\%$ of the $375$ students ride the bus. Of those who ride the bus, $15\\%$ live more than $10$ miles from school. How many bus riders live more than $10$ miles from school?', NULL, $lyceon_json$[{"key":"A","text":"$36$"},{"key":"B","text":"$46$"},{"key":"C","text":"$56$"},{"key":"D","text":"$240$"}]$lyceon_json$::jsonb, 'A', NULL, E'The number of bus riders is $0.64 \\times 375 = 240$. Of those, $15\\%$ live more than $10$ miles away: $0.15 \\times 240 = 36$. The distractor $46$ results from an arithmetic error such as computing $0.64 \\times 375$ as $250$ and then taking $15\\%$ incorrectly. The distractor $56$ results from applying $15\\%$ to $375$ instead of to the bus riders only ($0.15 \\times 375 = 56.25 \\approx 56$). The distractor $240$ is the number of bus riders, stopping before the second step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PI9ENA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $4$ cm and a height of $11$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$176\\pi$ cm$^3$"},{"key":"B","text":"$88\\pi$ cm$^3$"},{"key":"C","text":"$44\\pi$ cm$^3$"},{"key":"D","text":"$352\\pi$ cm$^3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(4)^2(11) = 176\\pi$ cm$^3$. The value $88\\pi$ results from using the diameter in place of the radius but then halving, computing $\\pi \\times 8 \\times 11 = 88\\pi$. The value $44\\pi$ results from using $\\pi r h = \\pi \\times 4 \\times 11 = 44\\pi$, forgetting to square the radius. The value $352\\pi$ results from using the diameter squared instead of the radius squared, computing $\\pi \\times 64 \\times 11 / 2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PT7O16', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands $47$ meters from the base of a building and measures the angle of elevation to the top as $58°$. She then measures the angle of elevation to the tip of an antenna on the roof as $63°$. What is the height of the antenna alone, to the nearest tenth of a meter? (Use $\\tan(58°) \\approx 1.6003$ and $\\tan(63°) \\approx 1.9626$.)', NULL, $lyceon_json$[{"key":"A","text":"$17.0$"},{"key":"B","text":"$92.2$"},{"key":"C","text":"$75.2$"},{"key":"D","text":"$22.4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The height to the antenna tip is $47 \\times \\tan(63°) = 47 \\times 1.9626 \\approx 92.2$ m. The height to the rooftop is $47 \\times \\tan(58°) = 47 \\times 1.6003 \\approx 75.2$ m. The antenna height is $92.2 - 75.2 = 17.0$ m. The value $92.2$ gives the total height to the antenna tip rather than the antenna alone. The value $75.2$ gives the building height only, stopping before computing the difference. The value $22.4$ results from subtracting the tangent values first and then applying a miscalculated scaling factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PXIXE8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, the side opposite the $37°$ angle has length $11$. What is the length of the hypotenuse, to the nearest tenth? (Use $\\sin(37°) \\approx 0.6018$.)', NULL, $lyceon_json$[{"key":"A","text":"$18.3$"},{"key":"B","text":"$6.6$"},{"key":"C","text":"$13.8$"},{"key":"D","text":"$14.6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $\\sin(37°) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{11}{h}$, solving gives $h = \\frac{11}{0.6018} \\approx 18.3$. The value $6.6$ results from multiplying $11 \\times 0.6018$ instead of dividing, confusing the relationship. The value $13.8$ comes from using cosine instead of sine, computing $\\frac{11}{0.7986}$, which applies the wrong trigonometric ratio. The value $14.6$ results from an arithmetic error in the division.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T8FNFB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $DEF$, side $DE = 17$, side $EF = 23$, and side $DF = 29$. Which of the following correctly orders the angles of the triangle from smallest to largest?', NULL, $lyceon_json$[{"key":"A","text":"Angle $F$, angle $D$, angle $E$"},{"key":"B","text":"Angle $D$, angle $F$, angle $E$"},{"key":"C","text":"Angle $E$, angle $D$, angle $F$"},{"key":"D","text":"Angle $F$, angle $E$, angle $D$"}]$lyceon_json$::jsonb, 'A', NULL, E'In any triangle, the smallest angle is opposite the shortest side and the largest angle is opposite the longest side. Side $DE = 17$ (shortest) is opposite angle $F$, side $EF = 23$ is opposite angle $D$, and side $DF = 29$ (longest) is opposite angle $E$. So the order from smallest to largest is angle $F$, angle $D$, angle $E$. The ordering angle $D$, angle $F$, angle $E$ incorrectly places angle $D$ as the smallest, confusing which angle is opposite which side. The ordering angle $E$, angle $D$, angle $F$ reverses the relationship, placing the largest angle first. The ordering angle $F$, angle $E$, angle $D$ correctly identifies the smallest angle but swaps the remaining two, failing to trace the side-angle correspondence for the middle values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TS5T9V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours studied and the score on a test for $12$ students. The line of best fit is $y = 7x + 43$, where $x$ is the number of hours studied and $y$ is the test score. According to the line of best fit, what is the predicted test score for a student who studies for $6$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$78$"},{"key":"B","text":"$81$"},{"key":"C","text":"$85$"},{"key":"D","text":"$92$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 6$ into the equation: $y = 7(6) + 43 = 42 + 43 = 85$. The distractor $78$ results from computing $7 \\times 6 = 42$ and adding $36$ instead of $43$. The distractor $81$ comes from an arithmetic error such as computing $7 \\times 6 = 38$ and adding $43$. The distractor $92$ results from incorrectly computing $7 \\times 7 + 43 = 92$, using $x = 7$ instead of $x = 6$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V2MCR0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle has center $(2, -3)$ and passes through the point $(9, 21)$. What is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 2)^2 + (y + 3)^2 = 625$"},{"key":"B","text":"$(x - 2)^2 + (y + 3)^2 = 25$"},{"key":"C","text":"$(x + 2)^2 + (y - 3)^2 = 625$"},{"key":"D","text":"$(x - 2)^2 + (y - 3)^2 = 625$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from the center $(2, -3)$ to the point $(9, 21)$: $r = \\sqrt{(9-2)^2 + (21-(-3))^2} = \\sqrt{49 + 576} = \\sqrt{625} = 25$. So $r^2 = 625$ and the equation is $(x - 2)^2 + (y + 3)^2 = 625$. The equation with $r^2 = 25$ uses the radius value itself instead of its square, a common error of forgetting to square $r$ in the standard form. The equation $(x + 2)^2 + (y - 3)^2 = 625$ reverses the signs of both $h$ and $k$ in the standard form. The equation $(x - 2)^2 + (y - 3)^2 = 625$ uses the wrong sign for the $y$-coordinate of the center, writing $(y - 3)$ instead of $(y + 3)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VJK1AD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university conducted a study to test whether listening to instrumental music while studying improves exam scores. Researchers recruited 150 volunteers and randomly assigned 75 to study with instrumental music and 75 to study in silence. The music group scored an average of 4.7 points higher on the exam, and the difference was statistically significant (p < 0.03). However, all 150 volunteers were music majors. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Listening to instrumental music while studying causes higher exam scores for all university students."},{"key":"B","text":"Listening to instrumental music while studying causes higher exam scores for music majors at this university."},{"key":"C","text":"There is an association, but not necessarily a causal relationship, between listening to instrumental music and higher exam scores for music majors."},{"key":"D","text":"The study is invalid because the sample consisted entirely of music majors."}]$lyceon_json$::jsonb, 'B', NULL, E'Because treatments were randomly assigned, a causal conclusion is supported. However, because the sample consisted entirely of music majors (not a random sample of all university students), the results can only be generalized to music majors at this university. The conclusion that the effect applies to all university students overgeneralizes beyond the population studied. The claim that only an association exists ignores that random assignment of treatments supports a causal inference — the limitation here is generalizability, not causality. The claim that the study is invalid misunderstands that a non-representative sample limits generalizability but does not invalidate the experiment''s internal design; random assignment still supports a causal conclusion within the studied population.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VXFTM7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages of $5$ volunteers at a community event are $19$, $23$, $27$, $31$, and $35$. What is the mean age of the volunteers?', NULL, $lyceon_json$[{"key":"A","text":"$25$"},{"key":"B","text":"$27$"},{"key":"C","text":"$29$"},{"key":"D","text":"$31$"}]$lyceon_json$::jsonb, 'B', NULL, E'The mean is $\\frac{19 + 23 + 27 + 31 + 35}{5} = \\frac{135}{5} = 27$. The distractor $25$ results from a summation error such as computing the total as $125$. The distractor $29$ comes from adding incorrectly to get $145$ and dividing by $5$. The distractor $31$ confuses the mean with the second-largest value rather than computing the average.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WSIGYA', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies the equation $$\\frac{2x + 9}{5} - \\frac{x - 3}{2} = 1\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$-23$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$23$"},{"key":"D","text":"$43$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying every term by $10$ gives $2(2x + 9) - 5(x - 3) = 10$. Distributing: $4x + 18 - 5x + 15 = 10$, which simplifies to $-x + 33 = 10$, so $x = 23$. The value $-23$ results from a sign error when isolating $x$. The value $-7$ arises from incorrectly distributing $-5(x - 3)$ as $-5x - 15$, yielding $-x + 3 = 10$. The value $43$ comes from incorrectly computing $33 + 10$ instead of $33 - 10$ when solving $-x + 33 = 10$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XQVD32', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally costs $\\$130$. It is on sale for $35\\%$ off. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$45.50$"},{"key":"B","text":"$\\$84.50$"},{"key":"C","text":"$\\$95.00$"},{"key":"D","text":"$\\$97.50$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is $0.35 \\times 130 = 45.50$. The sale price is $130 - 45.50 = 84.50$. The distractor $\\$45.50$ gives only the discount amount, not the sale price. The distractor $\\$95.00$ results from subtracting $35$ directly from $130$ instead of computing the percentage. The distractor $\\$97.50$ comes from incorrectly computing $130 \\times 0.25$ and subtracting, confusing $35\\%$ with $25\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YDG8PW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The system of equations below has two solutions. Which of the following is one of the solutions?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2050NZQ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the team''s explanation for their results?', E'A team of neuroscientists led by Hana Kovačević at Charles University in Prague conducted a study in which participants memorized a series of forty abstract symbols. Half the participants studied the symbols while listening to a recording of rainfall, and half studied in silence. When tested twenty-four hours later, the rainfall group recalled an average of 27 symbols correctly, compared with 21 for the silent group. The team attributed this difference to the phenomenon of "auditory gating": they proposed that continuous ambient sound activates inhibitory circuits in the prefrontal cortex that suppress task-irrelevant neural activity, effectively sharpening focus on the visual memorization task.', $lyceon_json$[{"key":"A","text":"Participants who studied while listening to rainfall reported feeling more relaxed than those who studied in silence, and self-reported relaxation correlated with higher recall scores across both groups."},{"key":"B","text":"Functional MRI scans taken during the study phase showed that the rainfall group exhibited greater prefrontal cortex inhibitory activity than the silent group."},{"key":"C","text":"When the experiment was repeated with participants who had significant hearing loss in both ears, the rainfall group and the silent group achieved nearly identical recall scores."},{"key":"D","text":"A follow-up study found that participants who studied while listening to spoken-word podcasts recalled fewer symbols than those who studied in silence."}]$lyceon_json$::jsonb, 'A', NULL, E'The team''s explanation attributes improved recall specifically to auditory gating — inhibitory circuits suppressing irrelevant neural activity. The finding that relaxation correlated with higher recall across both groups provides an alternative explanation: the rainfall may have improved performance by inducing relaxation rather than through auditory gating, directly undermining the proposed mechanism. The finding about greater prefrontal inhibitory activity in the rainfall group would support, not undermine, the auditory gating explanation. The finding about participants with hearing loss achieving equal scores is consistent with auditory gating (no sound perception means no gating activation), so it does not undermine the explanation — it arguably supports it. The finding about spoken-word podcasts reducing recall addresses a different type of auditory input (meaningful speech) and does not challenge the specific mechanism proposed for continuous ambient sound.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21MV2XL', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Genomicist Priya Venkataraman has found that the New Zealand kākāpō, a critically endangered flightless parrot with a population of roughly 247 individuals, shows remarkably low genetic diversity — a condition that typically accelerates a species'' decline by reducing its ability to adapt to new diseases. _______ Venkataraman''s analysis revealed that the kākāpō genome contains unusually few harmful recessive mutations, suggesting that centuries of small population size have already purged the most deleterious genetic variants through natural selection.', $lyceon_json$[{"key":"A","text":"Additionally,"},{"key":"B","text":"As a result,"},{"key":"C","text":"Paradoxically,"},{"key":"D","text":"In summary,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence establishes that low genetic diversity typically harms a species, but the second sentence presents a surprising counterpoint: the kākāpō genome actually has fewer harmful mutations because of its small population history. This is a genuinely paradoxical finding — the expected negative outcome (accelerated decline) did not fully materialize because of an unexpected mechanism (purging of deleterious variants). "Paradoxically," captures this surprising contradiction. "Additionally," merely adds information without signaling the tension between expectation and reality, missing the key logical relationship. "As a result," implies the second sentence is a consequence of low genetic diversity being harmful, when in fact the finding contradicts that expected consequence. "In summary," signals a recap of prior information, but the second sentence introduces new findings rather than summarizing what was already stated.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW231X9UO', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Architectural historian Priya Chandrasekaran has documented how the builders of 11th-century Chola temples in Tamil Nadu oriented each structure to align with specific astronomical events. The Brihadeshwara Temple at Thanjavur, for instance, casts no shadow at noon during the spring equinox. Chandrasekaran argues that such alignments were not incidental but reflected a deliberate integration of cosmological knowledge into sacred architecture.', $lyceon_json$[{"key":"A","text":"It provides a specific example that supports the claim made in the previous sentence."},{"key":"B","text":"It introduces a counterargument to the passage's central thesis."},{"key":"C","text":"It defines a technical term used elsewhere in the passage."},{"key":"D","text":"It summarizes the overall findings of Chandrasekaran's research."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence about the Brihadeshwara Temple casting no shadow at noon during the spring equinox serves as a concrete instance of the astronomical alignments described in the preceding sentence. It provides a specific example supporting the claim that Chola temple builders oriented structures to align with astronomical events. The sentence does not introduce a counterargument — it reinforces the existing claim. It does not define any technical term. While it relates to Chandrasekaran''s research, it presents one illustration rather than summarizing her overall findings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW232MKUT', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a presentation for a college environmental science class about the ecological consequences of the decline of gray wolves in the northern Rocky Mountains. The student wants to present a cause-and-effect relationship between wolf population decline and changes in vegetation. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW236K2NJ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø in Norway have documented a surprising behavior in Arctic reindeer: their eyes change color with the seasons. During the long summer months of continuous daylight, the tapetum lucidum — a reflective layer behind the retina — appears golden. In the near-total darkness of winter, however, it shifts to a deep blue. The blue tapetum scatters light within the eye, increasing sensitivity to the dim illumination available. This seasonal adaptation, the researchers note, is unique among mammals and may help reindeer detect predators and forage during the polar night.', $lyceon_json$[{"key":"A","text":"Arctic reindeer have evolved a seasonal change in eye color that enhances their vision in winter darkness."},{"key":"B","text":"The tapetum lucidum is a reflective structure found exclusively in Arctic reindeer."},{"key":"C","text":"Researchers have recently discovered that reindeer migrate based on changes in light conditions."},{"key":"D","text":"Reindeer in Norway face significant threats from predators during all seasons of the year."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Arctic reindeer eyes change color between seasons, with the winter blue tapetum increasing light sensitivity — making the choice about a seasonal eye-color change enhancing winter vision the best summary of the main idea. The option claiming the tapetum lucidum is exclusive to reindeer misreads the passage, which says the seasonal adaptation is unique, not the structure itself. The option about migration based on light conditions introduces a claim not present in the text. The option about year-round predator threats overgeneralizes; the passage mentions predator detection only in the context of winter darkness.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23GOZ2P', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively illustrate the claim made in the text?', E'Literary scholars have increasingly argued that the novels of Igbo-Nigerian author Chinua Achebe do more than chronicle the disruptions of colonialism — they also encode within their narrative structures the oral storytelling traditions of Igbo culture. According to this view, Achebe''s frequent use of proverbs, embedded folk tales, and cyclical plot patterns reflects a deliberate effort to embed indigenous epistemology into the Western novel form, challenging the assumption that the novel is an exclusively European literary invention.', $lyceon_json$[{"key":"A","text":"\"In Things Fall Apart, the recurring proverb 'When the moon is shining the cripple becomes hungry for a walk' functions not as decoration but as an argumentative pivot, shifting the reader's interpretive frame from linear causation to communal wisdom.\""},{"key":"B","text":"\"Achebe's spare prose style, with its short declarative sentences and limited use of metaphor, reflects the influence of Ernest Hemingway more than any African oral tradition.\""},{"key":"C","text":"\"The commercial success of Achebe's novels in Western markets demonstrates that African literature can compete economically with European and American fiction.\""},{"key":"D","text":"\"Achebe's decision to write in English rather than Igbo has been criticized by some scholars as a concession to the colonial linguistic framework he sought to resist.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage claims Achebe embeds Igbo oral traditions — proverbs, folk tales, cyclical patterns — into the novel form to challenge its status as a European invention. The quotation analyzing how a specific proverb in Things Fall Apart functions as a structural argumentative device directly illustrates this embedding of indigenous epistemology. The quotation attributing Achebe''s style to Hemingway contradicts rather than supports the claim about oral tradition. The quotation about commercial success addresses market performance, which is unrelated to narrative structure or oral tradition. The quotation about the controversy over writing in English raises a different critical debate about language choice rather than illustrating how oral traditions are structurally embedded in the novels.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23HTFA7', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After analyzing spectral data from the Kepler space telescope, astrophysicist Nadia Okonkwo reached an unexpected ______ the exoplanet''s atmosphere contained molecular signatures consistent with biological activity, a finding that contradicted prevailing models of planetary habitability.', $lyceon_json$[{"key":"A","text":"conclusion: the"},{"key":"B","text":"conclusion, the"},{"key":"C","text":"conclusion is the"},{"key":"D","text":"conclusion, which the"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence structure requires punctuation after "conclusion" that introduces the content of the conclusion itself. The option using a colon correctly signals that what follows specifies or elaborates on the "unexpected conclusion"—a standard use of the colon to introduce an explanation or amplification. The option using only a comma creates a comma splice, improperly joining two independent clauses ("Okonkwo reached an unexpected conclusion" and "the exoplanet''s atmosphere contained molecular signatures...") with nothing more than a comma. The option inserting "is" produces a garbled construction ("reached an unexpected conclusion is the exoplanet''s atmosphere contained...") that lacks grammatical coherence. The option inserting "which" after a comma produces the ungrammatical fragment "conclusion, which the exoplanet''s atmosphere contained molecular signatures," where "which" has no syntactic role in the clause that follows it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23O3WEO', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Neuroscientist Yael Orenthal''s 2019 longitudinal study challenged the prevailing assumption that the adult prefrontal cortex is largely fixed in its connectivity patterns. Orenthal''s team tracked 137 participants over four years, documenting that prefrontal networks remained remarkably plastic even in subjects over sixty, reorganizing in response to sustained cognitive demands such as learning a tonal language.', $lyceon_json$[{"key":"A","text":"adaptable"},{"key":"B","text":"synthetic"},{"key":"C","text":"fragile"},{"key":"D","text":"visible"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that prefrontal networks were "reorganizing in response to sustained cognitive demands," directly indicating that "plastic" means adaptable — capable of changing form or function. "Synthetic" refers to artificial material, which is incoherent when describing neural networks in the brain. "Fragile" means easily broken, but the passage emphasizes the brain''s capacity to reorganize, not its vulnerability. "Visible" means able to be seen, which has no connection to the passage''s discussion of neural reorganization in response to cognitive challenge.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25UAT8V', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the preliminary geological survey nor the subsequent seismic analyses conducted by the team of researchers from the University of Reykjavik ______ any indication that the dormant caldera posed an imminent threat to the nearby coastal settlements.', $lyceon_json$[{"key":"A","text":"provides"},{"key":"B","text":"provide"},{"key":"C","text":"has provided"},{"key":"D","text":"is providing"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb must agree in number with the subject closer to it. Here, "the subsequent seismic analyses conducted by the team of researchers from the University of Reykjavik" is the nearer subject and is plural, so the verb must also be plural. The plural form "provide" correctly agrees with the nearer subject "analyses." The singular form "provides" incorrectly agrees with the more distant singular subject "survey" rather than the nearer plural subject. The singular "has provided" makes the same agreement error while also shifting to present perfect without contextual justification. The singular progressive "is providing" again fails to agree with the plural nearer subject and inappropriately implies an ongoing action rather than a completed finding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26GBDDX', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The seventeenth-century manuscript that the conservators painstakingly restored over a period of eleven ______ detailed navigational charts suggesting that Polynesian seafarers may have reached the western coast of South America decades before European explorers.', $lyceon_json$[{"key":"A","text":"months, contains"},{"key":"B","text":"months; contains"},{"key":"C","text":"months contains"},{"key":"D","text":"months. Contains"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence''s subject is "The seventeenth-century manuscript," modified by the restrictive relative clause "that the conservators painstakingly restored over a period of eleven months." Because this clause is restrictive—it identifies which manuscript is meant—no punctuation should separate it from the rest of the sentence. The main verb "contains" must follow directly after the clause closes at "months." The option with no punctuation between "months" and "contains" correctly preserves the subject-verb connection. The option inserting a comma incorrectly separates the subject from its predicate, as though the restrictive clause were parenthetical. The option using a semicolon splits a single sentence into two fragments: the portion before the semicolon lacks a main verb, and "contains detailed navigational charts..." lacks a subject. The option using a period creates the same fragment problem, leaving "Contains detailed navigational charts..." as a subjectless sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28NEWTR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The traditional view among art historians has been that the Nabataeans of Petra carved their elaborate rock-cut facades purely as tombs for their elite. Recent excavations led by archaeologist Laila Nehmé, however, have uncovered evidence of communal dining halls and water-channeling systems within several of these structures. _______ Nehmé has proposed that the facades served a dual civic and funerary function, hosting large public feasts as part of the Nabataean ancestor-veneration rituals.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"On this basis,"},{"key":"C","text":"By contrast,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'B', NULL, E'The preceding sentence presents archaeological evidence (dining halls and water-channeling systems), and the sentence following the blank draws a conclusion from that evidence (the facades served a dual function). "On this basis," correctly signals that the conclusion rests on the evidence just presented. "In other words," implies a restatement or paraphrase of the same idea, but the conclusion about dual civic and funerary function introduces a new interpretive claim rather than restating the evidence. "By contrast," signals opposition, yet Nehmé''s proposal builds on the new evidence rather than contradicting it. "For instance," would introduce a specific example of a previously stated general claim, but the sentence following the blank is a broader interpretive conclusion, not an example.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AC2VA0', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 2019, marine biologist Ayana Okoro published findings on the giant Pacific octopus''s ability to recognize individual human faces. In a controlled experiment at the Hatfield Marine Science Center in Oregon, Okoro''s team had two staff members interact with the same octopus over a period of eleven weeks: one person consistently fed the animal, while the other touched it with a bristly stick. When later presented with both individuals — neither carrying food or a stick — the octopus reliably approached the feeder and retreated from the other, even when the two wore identical clothing. Okoro argues that this demonstrates not merely associative learning but genuine individual recognition, a cognitive feat previously attributed only to vertebrates with significantly larger brains.', $lyceon_json$[{"key":"A","text":"An experiment showed that a giant Pacific octopus can distinguish between individual humans, suggesting a cognitive ability once thought limited to larger-brained vertebrates."},{"key":"B","text":"Giant Pacific octopuses are more intelligent than all other invertebrates because of their capacity for facial recognition."},{"key":"C","text":"A marine biologist conducted an experiment demonstrating that octopuses prefer human contact over isolation in laboratory settings."},{"key":"D","text":"The giant Pacific octopus relies primarily on visual cues rather than chemical signals to identify potential food sources."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes an experiment in which an octopus distinguished between two individuals and argues this constitutes individual recognition previously attributed only to larger-brained vertebrates — the choice summarizing that finding captures the main idea. The option claiming octopuses are more intelligent than all other invertebrates overgeneralizes beyond the passage''s specific claim about individual recognition. The option about octopuses preferring human contact misrepresents the experiment, which tested recognition, not social preference. The option about relying on visual cues for food identification focuses on a narrow mechanism the passage does not actually isolate; the experiment tested recognition of people, not identification of food sources.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BFS9VJ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The city council''s proposal mandates that each historic building in the waterfront district ______ a comprehensive structural assessment before any renovation permits can be issued, a requirement that preservationists have long advocated.', $lyceon_json$[{"key":"A","text":"undergoes"},{"key":"B","text":"undergo"},{"key":"C","text":"will undergo"},{"key":"D","text":"underwent"}]$lyceon_json$::jsonb, 'B', NULL, E'The verb "mandates" triggers the subjunctive mood in the "that" clause that follows it. In English, verbs of demand, recommendation, or requirement (such as "mandates," "requires," "insists") call for the base form of the verb in the subordinate clause, regardless of the subject''s number. The base form "undergo" is the correct subjunctive form after "mandates that each historic building." The indicative form "undergoes" incorrectly applies the standard third-person singular conjugation, ignoring the subjunctive requirement imposed by "mandates." The future form "will undergo" incorrectly adds the modal auxiliary "will," which is incompatible with the subjunctive construction. The past tense "underwent" introduces an incorrect time frame; the mandate concerns a current or future requirement, and the subjunctive does not take past tense in this construction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BH5IX1', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "volatile" most nearly mean?', E'In 1883, the volcanic island of Krakatoa underwent a catastrophic eruption that reshaped the surrounding geography. Geologists studying the region have noted that the area remains volatile, with frequent seismic tremors and gas emissions indicating continued tectonic instability beneath the ocean floor.', $lyceon_json$[{"key":"A","text":"unstable"},{"key":"B","text":"furious"},{"key":"C","text":"flammable"},{"key":"D","text":"temporary"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes an area with "frequent seismic tremors and gas emissions indicating continued tectonic instability," so "volatile" means unstable — subject to sudden, unpredictable change. "Furious" implies intense anger, which does not apply to a geological region. "Flammable" relates to combustibility, not tectonic activity. "Temporary" suggests something short-lived, but the passage emphasizes ongoing instability, not brevity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DCCLPO', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the 1970s, ethnomusicologist Halim El-Dabh argued that ancient Egyptian temple ceremonies incorporated polyrhythmic drumming traditions that predated and influenced West African musical practices. Few scholars accepted El-Dabh''s hypothesis at the time, citing a lack of physical evidence. In 2019, however, archaeologist Nour Abdel-Fattah discovered a set of seventeen carved bone percussion instruments in a sealed ritual chamber beneath the Temple of Hathor at Dendera, with carbon dating placing them at approximately 2300 BCE. _______ several ethnomusicologists have noted that the spacing and wear patterns on the Dendera instruments are consistent with the polyrhythmic techniques El-Dabh described, though they caution that consistency does not establish a direct transmission pathway to later West African traditions.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Granted,"},{"key":"C","text":"In turn,"},{"key":"D","text":"Regardless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank describes a physical archaeological discovery (the Dendera instruments) that lends some support to El-Dabh''s hypothesis. The sentence after the blank adds a further piece of supporting evidence — ethnomusicologists finding the instruments'' wear patterns consistent with El-Dabh''s claims — while tempering the conclusion. "Furthermore," correctly signals an additional supporting point that builds on the archaeological discovery. "Granted," introduces a concession, implying the following sentence acknowledges a counterargument, but the ethnomusicologists'' observation actually reinforces the preceding evidence rather than conceding a point against it. "In turn," implies a sequential or reciprocal causal chain, but the ethnomusicologists'' analysis is an independent corroborating observation, not a caused reaction. "Regardless," signals that the following sentence proceeds despite a preceding obstacle, but no obstacle has been presented — the discovery of the instruments was itself supportive evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DNJ36K', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Hirola antelope, a critically endangered species found only in a narrow strip of grassland along the Kenya-Somalia ______ has declined from an estimated fourteen thousand individuals in the 1970s to fewer than five hundred today, making it one of the rarest large mammals on Earth.', $lyceon_json$[{"key":"A","text":"border, has"},{"key":"B","text":"border; has"},{"key":"C","text":"border. Has"},{"key":"D","text":"border has"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence contains a nonrestrictive appositive ("a critically endangered species found only in a narrow strip of grassland along the Kenya-Somalia border") that is set off from the main clause. Because the appositive is introduced by a comma after "antelope," a matching comma is needed after "border" to close it and reconnect the subject ("The Hirola antelope") with its verb ("has declined"). The option using a comma after "border" correctly closes the appositive. The option using a semicolon incorrectly separates the subject from its verb, breaking the sentence into a fragment before the semicolon and another fragment after it. The option using a period creates the fragment "Has declined from an estimated fourteen thousand individuals," which lacks a subject. The option omitting all punctuation after "border" fails to close the nonrestrictive appositive, violating the convention that paired commas must set off such phrases.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FP9EHV', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IBBPOY', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists at the Farallon Islands research station have documented a 37 percent decline in the local population of Cassin''s auklets over the past eleven years. _______ the researchers have recommended that commercial fishing vessels be prohibited from operating within a fifteen-kilometer radius of the islands during the auklet breeding season.', $lyceon_json$[{"key":"A","text":"Consequently,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents a finding (a 37 percent decline in auklet population) followed by a recommendation (prohibiting commercial fishing near the islands). The second sentence is a result or consequence of the first, so "Consequently," correctly signals this cause-and-effect relationship. "Nevertheless," incorrectly signals a contrast, when the recommendation logically follows from the decline rather than contradicting it. "Specifically," implies the second sentence narrows or elaborates on a general claim, but the recommendation is not a more specific version of the decline data. "Meanwhile," suggests two simultaneous but unrelated events, which mischaracterizes the logical dependence between the finding and the recommendation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KSWUCM', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'The ceramicist Luisa Mantovani is celebrated for vessels whose glazes appear spontaneous — splashes of cobalt and celadon that seem to have landed by chance. In interviews, however, Mantovani has tempered the romantic notion of her process, explaining that each glaze application follows a precise sequence of layering and kiln-temperature adjustments developed over nineteen years of methodical experimentation.', $lyceon_json$[{"key":"A","text":"moderated"},{"key":"B","text":"heated"},{"key":"C","text":"provoked"},{"key":"D","text":"abandoned"}]$lyceon_json$::jsonb, 'A', NULL, E'Mantovani has not rejected the romantic notion entirely but has qualified it by revealing the methodical reality behind her work. "Moderated" captures this act of softening or qualifying an extreme perception. "Heated" refers to raising temperature, which is incoherent when applied to a notion. "Provoked" means to incite or stimulate, the opposite of qualifying a perception. "Abandoned" implies complete rejection, but the passage indicates she qualifies the notion rather than discarding it outright, since her glazes do still appear spontaneous — she simply contextualizes the process behind them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KW4BGR', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Economist Dalia Rennert has proposed that the "productivity paradox" of the 1990s — the observation that massive corporate investment in information technology initially yielded no measurable gains in output — arose not from the technology itself but from organizational inertia. Firms, Rennert argues, grafted new digital tools onto workflows designed for paper-based processes, neutralizing the efficiency gains the tools were engineered to deliver.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M0UQ5T', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, marine biologists assumed that deep-sea bioluminescence served primarily as a predator-avoidance mechanism, allowing organisms to blend with faint surface light through counterillumination. Recent observations from remotely operated vehicles at hadal depths, however, have revealed bioluminescent displays in species that face no visually hunting predators whatsoever. These findings have prompted researchers to investigate alternative functions, including intraspecies signaling and the attraction of symbiotic microorganisms to nutrient-poor body surfaces.', $lyceon_json$[{"key":"A","text":"It presents a longstanding assumption, introduces evidence that challenges it, and describes the new lines of inquiry that resulted."},{"key":"B","text":"It compares two competing theories and argues that one is more supported by evidence than the other."},{"key":"C","text":"It describes a biological phenomenon, traces its evolutionary origins, and predicts its future development."},{"key":"D","text":"It outlines a research method, details its application to a specific species, and evaluates its limitations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first states the longstanding assumption about bioluminescence serving as predator avoidance, then presents ROV observations that challenge this assumption by revealing bioluminescence in species without visual predators, and finally describes the new research directions these findings have inspired. The passage does not compare two competing theories side by side — it presents one assumption and then evidence against it. It does not trace evolutionary origins or make predictions about future development. It does not outline a research method''s application to a specific species or evaluate methodological limitations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M93JQF', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the enzyme ribonuclease can refold into its functional shape after being chemically ______ most proteins lose their three-dimensional structure permanently when exposed to extreme heat or significant pH changes.', $lyceon_json$[{"key":"A","text":"denatured, most"},{"key":"B","text":"denatured; most"},{"key":"C","text":"denatured. Most"},{"key":"D","text":"denatured most"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with a dependent clause introduced by "Although," which must be followed by a comma before the independent clause that completes the thought. The option placing a comma after "denatured" correctly marks the boundary between the introductory dependent clause and the main clause. The option using a semicolon is incorrect because a semicolon joins two independent clauses, and the "Although" clause is dependent—it cannot stand on its own. The option using a period is incorrect for the same reason: placing a period after "denatured" would turn the "Although" clause into a sentence fragment. The option using no punctuation after "denatured" is incorrect because Standard English requires a comma after a long introductory dependent clause to signal where the main clause begins.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
