INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q2N77E', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research paper for an art history seminar about the pigment Egyptian blue. The student wants to contrast ancient and modern understandings of the pigment to highlight how recent scientific discoveries have revealed previously unknown properties. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R6MYZT', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the New Zealand kauri tree, Agathis australis, takes nearly three years to mature — one of the longest seed-development periods of any conifer. During this time, the developing cones remain tightly sealed and attached to the highest branches, far above the canopy floor. Ecologists have noted that this prolonged maturation period coincides with the typical interval between major cyclone events in the upper North Island. Because kauri seeds are dispersed by wind, researchers suggest that the extended development cycle may be an adaptation that ________', $lyceon_json$[{"key":"A","text":"ensures seeds are released during storm events whose high winds carry them farther from the parent tree."},{"key":"B","text":"allows the parent tree to conserve water during the dry season by keeping cones closed."},{"key":"C","text":"protects immature seeds from fungal infections that are most common at ground level."},{"key":"D","text":"prevents seed predation by native birds that feed primarily on mature cones."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that the maturation period matches the interval between cyclone events and that seeds are wind-dispersed. The logical completion is that this timing ensures seeds are released when high winds from storms can disperse them farther. The option about conserving water introduces a factor (dry-season water stress) not mentioned or implied in the passage. The option about fungal infections at ground level is unrelated to the cyclone-interval timing the passage highlights. The option about bird predation on mature cones introduces seed predation, which the passage does not address, and contradicts the logic by suggesting delaying maturation prevents predation on mature cones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RTZ6IB', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the research vessel reaches the Mariana Trench next spring, the international team of marine biologists aboard ______ three years refining the submersible''s pressure-resistant sampling apparatus.', $lyceon_json$[{"key":"A","text":"will spend"},{"key":"B","text":"would spend"},{"key":"C","text":"will have spent"},{"key":"D","text":"had spent"}]$lyceon_json$::jsonb, 'C', NULL, E'The phrase "By the time the research vessel reaches the Mariana Trench next spring" establishes a future deadline by which an action will already be completed. This construction requires the future perfect tense. The form "will have spent" correctly indicates an action that will be completed before a specified future moment. The simple future "will spend" fails to convey that the action will already be finished by the stated deadline. The conditional "would spend" introduces an inappropriate hypothetical tone, implying uncertainty rather than a factual timeline. The past perfect "had spent" is anchored to a past reference point and is incompatible with the future time frame established by "next spring."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RYY6VT', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Elif Arslan has studied the construction records of Ottoman-era caravanserais — roadside inns built to shelter merchants along trade routes. Arslan found that between 1450 and 1550, the average distance between newly constructed caravanserais along the Anatolian Silk Road decreased from roughly 40 kilometers to 25 kilometers. Over the same period, court records show a marked increase in complaints from provincial governors about bandit attacks on commercial caravans. Arslan argues that the closer spacing of caravanserais was not driven by an increase in trade volume, as previous historians had assumed, but rather by ________', $lyceon_json$[{"key":"A","text":"a strategic response to rising insecurity, reducing the distance merchants had to travel through unprotected territory."},{"key":"B","text":"a growing preference among merchants for smaller, more intimate lodging facilities along trade routes."},{"key":"C","text":"the Ottoman court's desire to display imperial wealth through ambitious architectural projects in remote provinces."},{"key":"D","text":"advances in construction techniques that made it possible to build caravanserais more quickly and cheaply."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage pairs two facts — decreasing distance between caravanserais and increasing bandit attacks — and states the historian rejects the trade-volume explanation. The logical inference is that closer spacing was a security measure to reduce unprotected travel distance. The option about merchant preference for smaller lodgings introduces a motive the passage neither states nor implies. The option about displaying imperial wealth through architecture has no connection to the bandit-attack evidence the passage foregrounds. The option about construction advances explains how more caravanserais could be built but does not address why they would be built closer together, ignoring the security context the passage establishes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T4HIX0', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists Priya Sengupta and Marco Díaz have proposed that the decline in monarch butterfly populations along the eastern migratory corridor is driven primarily by the loss of milkweed in agricultural regions of the Midwest, rather than by factors at the butterflies'' overwintering sites in central Mexico. Their hypothesis predicts that monarchs arriving in Mexico in recent years carry lower fat reserves than those arriving in earlier decades, because reduced milkweed availability forces longer searches for nectar during migration.', $lyceon_json$[{"key":"A","text":"Specimens collected at overwintering sites between 2010 and 2022 had an average body fat percentage 19% lower than specimens collected between 1980 and 1995."},{"key":"B","text":"The number of overwintering sites used by monarchs in central Mexico has remained stable over the past four decades."},{"key":"C","text":"Milkweed plants have been found to grow more densely along roadsides than in cultivated fields."},{"key":"D","text":"Monarch butterflies from the western migratory corridor have experienced a similar population decline in the same period."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis predicts that monarchs now arrive in Mexico with lower fat reserves due to milkweed loss during migration. The finding that specimens from recent decades had significantly lower body fat than earlier specimens directly confirms this prediction. The finding about stable overwintering sites addresses conditions in Mexico rather than the Midwest milkweed-loss mechanism the hypothesis concerns. The finding about milkweed density along roadsides versus fields describes milkweed distribution but does not address whether monarchs'' fat reserves have actually declined. The finding about western corridor monarchs introduces a different population whose decline could stem from unrelated causes and does not test the specific fat-reserve prediction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U77QH4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the function of the text as a whole?', E'The fruit fly Drosophila melanogaster has long been a workhorse of genetics research, prized for its short generation time and the ease with which its genome can be manipulated. Yet a 2021 study by Kenji Watanabe at Osaka University suggests that this very convenience may introduce a systematic blind spot. Watanabe''s team compared gene-expression profiles in laboratory-reared Drosophila with those of wild-caught flies from orchards near Nara. They found that 347 genes — including several involved in immune response and circadian regulation — were expressed at significantly different levels in the two populations. Some of these expression differences, the team showed, arose not from genetic divergence but from the stable, pathogen-free, and continuously lit environments of the laboratory. The implication is uncomfortable: decades of findings about immunity and sleep in Drosophila may reflect the artificial conditions of captivity rather than the biology of the species itself.', $lyceon_json$[{"key":"A","text":"It presents a research finding that calls into question the generalizability of laboratory-based studies using a widely relied-upon model organism."},{"key":"B","text":"It argues that wild Drosophila are genetically superior to laboratory-reared populations due to natural selection pressures."},{"key":"C","text":"It chronicles the historical importance of Drosophila melanogaster in genetics and advocates for its continued use in immunity research."},{"key":"D","text":"It contrasts two competing theories about why gene-expression differences arise between laboratory and wild insect populations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces Drosophila as a standard research organism, then presents Watanabe''s finding that laboratory conditions alter gene expression in ways that may undermine decades of findings — its overall function is to present research that questions the generalizability of lab-based studies using this model organism. The option about wild flies being genetically superior oversteps the passage, which attributes differences to environmental conditions, not genetic superiority through natural selection. The option describing a chronicle advocating continued use captures only the opening context and reverses the passage''s critical thrust. The option about two competing theories mischaracterizes the passage, which presents one study''s findings rather than a debate between rival theories.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
