INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XNKIYI', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief article about the baobab tree for a nature magazine aimed at general readers. The student wants to emphasize the tree''s unusual physical characteristics. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XP3USF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A new analysis of fossilized pollen grains collected from lakebeds across northern Scandinavia ______ that birch forests expanded rapidly during a brief warming period approximately 9,200 years ago.', $lyceon_json$[{"key":"A","text":"suggest"},{"key":"B","text":"suggests"},{"key":"C","text":"are suggesting"},{"key":"D","text":"have suggested"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "A new analysis," which is singular. The intervening prepositional phrases ("of fossilized pollen grains collected from lakebeds across northern Scandinavia") do not change the number of the subject. The singular third-person form "suggests" correctly agrees with "analysis." The bare plural form "suggest" fails to agree with the singular subject. The form "are suggesting" uses a plural auxiliary verb, which also fails to agree. The form "have suggested" likewise uses a plural auxiliary and incorrectly matches the plural nouns in the intervening phrases rather than the true singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YT7F59', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Paleoclimatologist Yuto Nakamura has analyzed isotopic ratios in stalagmites from Akiyoshi-dai cave in Yamaguchi Prefecture, Japan, to reconstruct regional rainfall patterns over the past 9,000 years. Nakamura found that between approximately 4,200 and 3,900 years ago — a period that coincides with the global "4.2-kiloyear event" associated with drought in the Middle East and North Africa — southwestern Japan experienced not a drought but a pronounced increase in precipitation. Nakamura attributes this apparent contradiction to the behavior of the East Asian monsoon: during periods when the Intertropical Convergence Zone (ITCZ) shifts southward, as it did during the 4.2-kiloyear event, moisture-laden air masses that would normally reach Southeast Asia are redirected toward the mid-latitude western Pacific. This finding implies that global climate events characterized as uniformly catastrophic may in fact ________', $lyceon_json$[{"key":"A","text":"produce opposing regional effects whose nature depends on the redistribution of atmospheric circulation patterns rather than on a single global mechanism."},{"key":"B","text":"have been exaggerated by researchers who relied too heavily on proxy data from a single geographic region."},{"key":"C","text":"be fully predictable once scientists achieve sufficiently detailed models of ocean surface temperatures."},{"key":"D","text":"affect only tropical and subtropical regions, leaving mid-latitude areas largely unchanged during periods of global climatic stress."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that the same global event produced drought in one region and increased rainfall in another, specifically because atmospheric circulation (the ITCZ) redirected moisture. The logical completion is that global climate events can produce opposing regional effects determined by atmospheric redistribution, not a uniform mechanism. The option claiming researchers exaggerated events based on single-region data introduces a critique of methodology the passage does not make — Nakamura adds nuance, not a charge of exaggeration. The option about full predictability through ocean-temperature models goes far beyond the passage''s evidence, which concerns one historical case, not a claim about prediction. The option stating mid-latitude areas are largely unchanged directly contradicts the passage''s central finding that southwestern Japan (a mid-latitude area) experienced significant precipitation increase.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
